import{_ as t,o as a,c as i,a2 as o}from"./chunks/framework.Dg5fKO7V.js";const u=JSON.parse('{"title":"Data, Privacy and Security","description":"","frontmatter":{},"headers":[],"relativePath":"Data-Privacy-And-Security.md","filePath":"Data-Privacy-And-Security.md","lastUpdated":1788563284000}'),r={name:"Data-Privacy-And-Security.md"};function n(d,e,s,c,h,l){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="data-privacy-and-security" tabindex="-1">Data, Privacy and Security <a class="header-anchor" href="#data-privacy-and-security" aria-label="Permalink to &quot;Data, Privacy and Security&quot;">​</a></h1><h2 id="what-stays-on-your-machine" tabindex="-1">What stays on your machine <a class="header-anchor" href="#what-stays-on-your-machine" aria-label="Permalink to &quot;What stays on your machine&quot;">​</a></h2><p>Everything. Profiles, library entries, watch progress, settings, the catalogue and every cache live in one SQLite database plus a few cache folders, under the operating system&#39;s application data directory:</p><table tabindex="0"><thead><tr><th>Platform</th><th>Location</th></tr></thead><tbody><tr><td>Windows</td><td><code>%APPDATA%\\com.anisphere.desktop\\</code></td></tr><tr><td>macOS</td><td><code>~/Library/Application Support/com.anisphere.desktop/</code></td></tr><tr><td>Linux</td><td><code>~/.local/share/com.anisphere.desktop/</code></td></tr></tbody></table><p>There is no AniSphere account, no server belonging to the project, and no telemetry. Nothing about what you watch is reported anywhere, unless you sign in to AniList yourself and switch on synchronisation, which then does exactly what you asked it to.</p><h2 id="what-leaves-your-machine" tabindex="-1">What leaves your machine <a class="header-anchor" href="#what-leaves-your-machine" aria-label="Permalink to &quot;What leaves your machine&quot;">​</a></h2><p>Only what a feature needs, when that feature runs.</p><table tabindex="0"><thead><tr><th>Host</th><th>When</th><th>What it learns</th></tr></thead><tbody><tr><td><code>github.com</code></td><td>Catalogue download and update checks</td><td>Your address, and that you use AniSphere</td></tr><tr><td><code>graphql.anilist.co</code></td><td>Metadata, and account sync when signed in</td><td>The titles being looked up</td></tr><tr><td><code>kitsu.io</code></td><td>Metadata fallback, rankings, episode titles and thumbnails</td><td>The titles being looked up</td></tr><tr><td><code>myanimelist.net</code></td><td>Importing a public list</td><td>The account name being imported</td></tr><tr><td><code>api.aniskip.com</code></td><td>Opening and ending timestamps</td><td>The episode being watched</td></tr><tr><td>Streaming providers</td><td>Searching, listing and playing</td><td>The titles and episodes requested</td></tr><tr><td><code>discord.com</code></td><td>Rich Presence, if enabled</td><td>The title and episode playing</td></tr><tr><td><code>ipwho.is</code></td><td>The connectivity map</td><td>Your address</td></tr><tr><td><code>youtube-nocookie.com</code></td><td>Trailers on the hover preview</td><td>That a trailer was shown</td></tr></tbody></table><p>Provider hosts are listed on the connectivity board inside the app, and each one is a separate module under <code>src-tauri/src/providers/</code>.</p><p>Images are not loaded by the WebView directly. They go through a loopback proxy that fetches them once and keeps the bytes on disk, so the same cover is never fetched twice and no page can be fingerprinted by its image requests.</p><h2 id="removing-it-all" tabindex="-1">Removing it all <a class="header-anchor" href="#removing-it-all" aria-label="Permalink to &quot;Removing it all&quot;">​</a></h2><p>Settings has a clear-cache action for the image and stream caches. To remove everything, delete the application data directory listed above. Downloads live wherever you pointed them and are not touched by that.</p><h2 id="security-boundaries" tabindex="-1">Security boundaries <a class="header-anchor" href="#security-boundaries" aria-label="Permalink to &quot;Security boundaries&quot;">​</a></h2><p>Some parts of the codebase are load-bearing for safety, and changing them deserves focused tests and a careful review rather than a drive-by edit:</p><ul><li>The content security policy in <code>src-tauri/tauri.conf.json</code></li><li>The Tauri capability allowlist in <code>src-tauri/capabilities/</code></li><li>The loopback proxy, which refuses anything but HTTPS and blocks private and loopback hosts so it cannot be turned into a probe of the local network</li><li>The AniList OAuth flow and the token store</li><li>The updater endpoint and its signature check</li></ul><h2 id="credentials" tabindex="-1">Credentials <a class="header-anchor" href="#credentials" aria-label="Permalink to &quot;Credentials&quot;">​</a></h2><p>There are none to protect. AniSphere signs in to AniList through the authorization flow desktop applications are meant to use: the browser does the signing in, the application never sees the password, and no client secret is compiled into the binary. A secret shipped inside an installer is a secret anyone can read out of it, so there is not one to read.</p><p>What is stored is the access token AniList hands back for the account you signed in with, in the application&#39;s own data directory, and it is only ever sent back to AniList. Signing out removes it.</p><p>Logs and diagnostics must never contain tokens, complete media URLs, personal data or private filesystem paths.</p><h2 id="reporting-a-vulnerability" tabindex="-1">Reporting a vulnerability <a class="header-anchor" href="#reporting-a-vulnerability" aria-label="Permalink to &quot;Reporting a vulnerability&quot;">​</a></h2><p>Through GitHub&#39;s private vulnerability reporting, under Security then Advisories, rather than a public issue. See <code>.github/SECURITY.md</code> in the repository.</p>',21)])])}const y=t(r,[["render",n]]);export{u as __pageData,y as default};
